## `spsc_ringbuf.c`

```c
#include "spsc_ringbuf.h"
#include <string.h>   /* memcpy */
#include <assert.h>

/* capacity は 2 の冪乗でなければならない */
static void assert_pow2(size_t n)
{
    assert(n > 0 && (n & (n - 1)) == 0);
}

void spsc_init(spsc_ringbuf_t *rb, void *buf,
               size_t elem_size, size_t capacity_pow2)
{
    assert_pow2(capacity_pow2);

    rb->buf       = buf;
    rb->elem_size = elem_size;
    rb->capacity  = capacity_pow2;
    rb->mask      = capacity_pow2 - 1;
    rb->head      = 0;
    rb->tail      = 0;
}

/* ---- Producer (ISR 側でも安全) ---- */
bool spsc_push(spsc_ringbuf_t *rb, const void *item)
{
    size_t h = rb->head;          /* 自分だけが触る */
    size_t t = rb->tail;          /* 他側を読む (volatile) */

    if (h - t >= rb->capacity) {  /* 満杯 */
        return false;
    }

    /* 1) データを書き込む */
    memcpy((char *)rb->buf + (h & rb->mask) * rb->elem_size,
           item, rb->elem_size);

    /* 2) データがメモリに届いたことを保証してから head を進める */
    SPSC_HW_BARRIER();            /* バッファ書込 → head 更新の順序保証 */
    rb->head = h + 1;

    return true;
}

/* ---- Consumer (ISR 側でも安全) ---- */
bool spsc_pop(spsc_ringbuf_t *rb, void *item)
{
    size_t t = rb->tail;          /* 自分だけが触る */
    size_t h = rb->head;          /* 他側を読む (volatile) */

    if (t == h) {                 /* 空 */
        return false;
    }

    /* 1) head が更新済みであることを保証してからデータを読む */
    SPSC_HW_BARRIER();            /* head 更新 → バッファ読取の順序保証 */

    memcpy(item,
           (char *)rb->buf + (t & rb->mask) * rb->elem_size,
           rb->elem_size);

    /* 2) tail を進める (consumer 側のみ) */
    rb->tail = t + 1;

    return true;
}

bool  spsc_is_empty(const spsc_ringbuf_t *rb) { return rb->head == rb->tail; }
bool  spsc_is_full (const spsc_ringbuf_t *rb) { return rb->head - rb->tail >= rb->capacity; }
size_t spsc_count  (const spsc_ringbuf_t *rb) { return rb->head - rb->tail; }
```

