## `ringbuf.h`

```c
/*
 * ringbuf.h – Interrupt-safe Single-Producer / Single-Consumer ring buffer
 *
 * 前提:
 *   - 生産者(producer)と消費者(consumer)はそれぞれ1つだけ (SPSC)
 *   - 片側がISR、もう片側がmainループでも安全
 *   - バッファサイズは 2 の冪乗 (1, 2, 4, 8, …)
 */
#ifndef RINGBUF_H
#define RINGBUF_H

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

/* ---- コンパイラバリア (GCC / Clang / ARMCC 等) ---- */
#if defined(__GNUC__) || defined(__clang__)
  #define RINGBUF_BARRIER()  __asm volatile("" ::: "memory")
#elif defined(_MSC_VER)
  #include <intrin.h>
  #define RINGBUF_BARRIER()  _ReadWriteBarrier()
#else
  #define RINGBUF_BARRIER()  /* fallback: volatile で代替 */
#endif

/* ---- 構造体 ---- */
typedef struct {
    uint32_t        mask;       /* size - 1  (ラップ用) */
    uint32_t        size;       /* 要素数 (2^n)          */
    volatile uint32_t head;     /* 生産者専用: 書き込み位置 */
    volatile uint32_t tail;     /* 消費者専用: 読み出し位置 */
    void           *buf;        /* 実データ (要素サイズ × size) */
    uint32_t        elem_size;  /* 1要素のバイト数 */
} ringbuf_t;

/* ---- API ---- */

/** バッファを初期化。size は 2 の冪乗でなければならない。 */
int  rb_init   (ringbuf_t *rb, void *buf, uint32_t size, uint32_t elem_size);

/** 生産者側: 1要素書き込み。成功: true / バッファフル: false */
bool rb_put    (ringbuf_t *rb, const void *data);

/** 生産者側: 残り空きスロット数 */
uint32_t rb_free_count (const ringbuf_t *rb);

/** 消費者側: 1要素読み出し。成功: true / 空: false */
bool rb_get    (ringbuf_t *rb, void *out);

/** 消費者側: 現在蓄積中の要素数 */
uint32_t rb_used_count (const ringbuf_t *rb);

/** 消費者側: バッファを空にする */
void rb_flush  (ringbuf_t *rb);

#endif /* RINGBUF_H */
```

