static bool is_pow2(uint32_t n) {
    return n != 0 && (n & (n - 1)) == 0;
}

int rb_init(ringbuf_t *rb, void *buf, uint32_t size, uint32_t elem_size)
{
    if (!is_pow2(size) || elem_size == 0 || size == 0)
        return -1;

    rb->buf       = buf;
    rb->size      = size;
    rb->mask      = size - 1;
    rb->elem_size = elem_size;
    rb->head      = 0;
    rb->tail      = 0;
    return 0;
}

/* -------- 生産者側 (ISR でも main でも可) -------- */
bool rb_put(ringbuf_t *rb, const void *data)
{
    uint32_t h = rb->head;          /* 自分のインデックス: volatile 読み */
    uint32_t t = rb->tail;          /* 相手のインデックス: volatile 読み */

    /* 空きスロット数 = size - (h - t)  (unsigned wrap-safe) */
    if ((h - t) >= rb->size)
        return false;               /* バッファフル */

    /* データ書き込み (まだ head を更新していないので消費者は見ない) */
    memcpy((uint8_t *)rb->buf + (h & rb->mask) * rb->elem_size,
           data, rb->elem_size);

    RINGBUF_BARRIER();              /* データ → head の順序を保証 */
    rb->head = h + 1;              /* 1ステップ進める */
    RINGBUF_BARRIER();              /* head 更新が ISR/main に見えるように */

    return true;
}

