## `spsc_ringbuf.h`

```c
/* spsc_ringbuf.h — Interrupt-safe Single-Producer / Single-Consumer ring buffer */
#ifndef SPSC_RINGBUF_H
#define SPSC_RINGBUF_H

#include <stdint.h>
#include <stddef.h>
#include <string.h>

/* ---------- 可搬性マクロ ---------- */
#if defined(__GNUC__) || defined(__clang__)
    #define RB_COMPILER_BARRIER()  __asm__ volatile("" ::: "memory")
    #define RB_STORE_BARRIER()     __atomic_store_n(&rb->head, rb->head, __ATOMIC_RELEASE)
    #define RB_LOAD_BARRIER()      __atomic_load_n(&rb->tail, __ATOMIC_ACQUIRE)
#else
    /* MSVC 等のフォールバック */
    #define RB_COMPILER_BARRIER()  /* 空 */
    #define RB_STORE_BARRIER()     RB_COMPILER_BARRIER()
    #define RB_LOAD_BARRIER()      RB_COMPILER_BARRIER()
#endif

/* ---------- 型定義 ---------- */
typedef struct {
    uint8_t        *buf;       /* 固定バッファ（呼び出し側が確保） */
    size_t          mask;      /* capacity - 1（2^n - 1）          */
    volatile size_t head;      /* 生産者（ISR）が更新              */
    volatile size_t tail;      /* 消費者（main）が更新            */
} spsc_ringbuf_t;

/* ---------- API ---------- */

/** バッファを初期化する。capacity は 2 の冪乗であること。 */
void spsc_init(spsc_ringbuf_t *rb, uint8_t *buf, size_t capacity);

/** 1 バイト書き込み（生産者側：ISR から呼ぶ）。満杯なら 0 を返す。 */
int spsc_write(spsc_ringbuf_t *rb, uint8_t byte);

/** 1 バイト読み取り（消費者側：main から呼ぶ）。空なら 0 を返す。 */
int spsc_read(spsc_ringbuf_t *rb, uint8_t *byte);

/** 連続 n バイト書き込み（生産者側）。書き込めた数を返す。 */
size_t spsc_write_bulk(spsc_ringbuf_t *rb, const void *data, size_t n);

/** 連続 n バイト読み取り（消費者側）。読み取れた数を返す。 */
size_t spsc_read_bulk(spsc_ringbuf_t *rb, void *data, size_t n);

/* ---------- 補助 ---------- */
static inline int   spsc_is_empty(const spsc_ringbuf_t *rb) { return rb->head == rb->tail; }
static inline int   spsc_is_full (const spsc_ringbuf_t *rb) { return (rb->head - rb->tail) == (rb->mask + 1); }
static inline size_t spsc_size(const spsc_ringbuf_t *rb)    { return rb->head - rb->tail; }

#endif /* SPSC_RINGBUF_H */
