## `spsc_ringbuf.c`

```c
/* spsc_ringbuf.c */
#include "spsc_ringbuf.h"

/* capacity が 2 の冪乗かチェック（開発時アサート用） */
#define RB_ASSERT_POW2(cap) ((cap) > 0 && ((cap) & ((cap) - 1)) == 0)

void spsc_init(spsc_ringbuf_t *rb, uint8_t *buf, size_t capacity)
{
    /* capacity は 2^n であること（マスク演算で剰余を置き換えるため） */
    if (!RB_ASSERT_POW2(capacity)) return;   /* 本番では abort() でも可 */

    rb->buf  = buf;
    rb->mask = capacity - 1;
    rb->head = 0;
    rb->tail = 0;
}

/* ---- 生産者（ISR 側） ---- */

int spsc_write(spsc_ringbuf_t *rb, uint8_t byte)
{
    size_t h = rb->head;          /* 自インデックス（ISR のみ書き込み） */
    size_t t = RB_LOAD_BARRIER(); /* 消費者 tail を最新で読む（ACQUIRE）*/

    /* 満杯チェック */
    if (h - t >= rb->mask + 1)
        return 0;

    rb->buf[h & rb->mask] = byte;

    RB_COMPILER_BARRIER();        /* データ書き込み → index 更新の順序保証 */
    rb->head = h + 1;             /* 生産者 tail は ISR しか触らない → 不要 */
    RB_STORE_BARRIER();           /* RELEASE: 消費者が次の read で確実に見る */

    return 1;
}

size_t spsc_write_bulk(spsc_ringbuf_t *rb, const void *data, size_t n)
{
    const uint8_t *src = (const uint8_t *)data;
    size_t h = rb->head;
    size_t t = RB_LOAD_BARRIER();
    size_t space = rb->mask + 1 - (h - t);
    if (n > space) n = space;

    for (size_t i = 0; i < n; i++)
        rb->buf[(h + i) & rb->mask] = src[i];

    RB_COMPILER_BARRIER();
    rb->head = h + n;
    RB_STORE_BARRIER();

    return n;
}

/* ---- 消費者（main 側） ---- */

int spsc_read(spsc_ringbuf_t *rb, uint8_t *byte)
{
    size_t t = rb->tail;          /* 自インデックス（main のみ書き込み） */
    size_t h = rb->head;          /* 生産者 head を最新で読む（ISR 更新済み）*/

    /* 空チェック */
    if (h == t)
        return 0;

    *byte = rb->buf[t & rb->mask];

    RB_COMPILER_BARRIER();        /* データ読み取り → index 更新の順序保証 */
